import re

def parse_duration(text):
    if not isinstance(text, str) or not re.fullmatch(r'(?:[0-9]+[hms])+', text):
        raise ValueError("invalid duration: %r" % (text,))
    units = {'h': 3600, 'm': 60, 's': 1}
    return sum(int(n) * units[u] for n, u in re.findall(r'([0-9]+)([hms])', text))

